package cl.bolsillo.app;
import android.widget.*;import org.json.*;import java.util.*;import java.time.*;
final class Subscriptions {
 static void row(MainActivity a,JSONObject r)throws Exception{long owed=0;JSONArray parts=r.optJSONArray("shares");if(parts!=null)for(int i=0;i<parts.length();i++)owed+=parts.getJSONObject(i).optLong("amount");String detail=MainActivity.shortDate(r.optString("next"))+" · "+(r.optBoolean("active")?(r.optBoolean("automatic")?"Programado":r.optBoolean("matchNotifications")?"Aviso":"Manual"):"Pausado");if(owed>0)detail+=" · Tú "+a.money(r.optLong("amount")-owed)+" · Otros "+a.money(owed);Modern.add(a.body,Modern.item(a,Modern.iconFor(r.optString("name")),r.optString("name"),detail,a.money(r.optLong("amount")),Glass.VIOLET,()->Forms.recurringMenu(a,r)),8);}
 static void screen(MainActivity a)throws Exception{JSONArray all=a.data.getJSONArray("recurring");long monthly=0;for(int i=0;i<all.length();i++){JSONObject r=all.getJSONObject(i);if(r.optBoolean("active")&&r.optString("type").equals("expense")){long amount=Finance.personalExpense(r);monthly+=r.optString("frequency").equals("weekly")?Math.round(amount*52d/12):r.optString("frequency").equals("yearly")?Math.round(amount/12d):amount;}}Modern.add(a.body,Modern.stat(a,"subscription","Tu parte al mes",a.money(monthly),Glass.VIOLET),8);Modern.section(a,"Tus servicios","Añadir",()->add(a,""));Modern.pair(a,Modern.quickAction(a,"netflix","Netflix",()->a.attempt(()->add(a,"Netflix"))),Modern.quickAction(a,"spotify","Spotify",()->a.attempt(()->add(a,"Spotify"))));List<JSONObject> sorted=new ArrayList<>();for(int i=0;i<all.length();i++)if(all.getJSONObject(i).optString("type").equals("expense"))sorted.add(all.getJSONObject(i));sorted.sort(Comparator.comparing(r->r.optString("next")));for(JSONObject r:sorted)row(a,r);if(sorted.isEmpty())a.caption("Organiza aquí los próximos cobros de tus servicios.");Modern.section(a,"Otros pagos","Crear",()->Forms.recurring(a));for(int i=0;i<all.length();i++)if(!all.getJSONObject(i).optString("type").equals("expense"))row(a,all.getJSONObject(i));}
 static void add(MainActivity a,String service)throws Exception{Forms.Form f=new Forms.Form(a,"Nueva suscripción");AutoCompleteTextView name=f.conceptField("Servicio",service,"expense");EditText amount=f.field("Monto en CLP","",true),date=f.field("Próximo cobro · fecha",Ledger.today(),false);Forms.Pick account=new Forms.Pick(f,"Cuenta","accounts","",""),category=new Forms.Pick(f,"Categoría","categories","expense",Detection.category(a,a.data,service));f.bindConcept(name,category,"expense");Spinner freq=f.select("Frecuencia",Arrays.asList("Mensual","Semanal","Anual"),0);Switch auto=f.toggle("Registrar desde notificaciones",true);SharesEditor shares=new SharesEditor(f,null);f.note("Al reconocer servicio, cuenta y monto cerca de su fecha, el aviso registra el gasto y avanza el próximo cobro. No se crea otro gasto programado.");f.save("Guardar suscripción",()->{Ledger.require(!Forms.value(name).isEmpty(),"Escribe el servicio");LocalDate next=LocalDate.parse(Forms.value(date));Ledger.require(shares.total()<=Forms.amount(amount,false),"Las partes superan el cobro");LocalData.upsert(a,"recurring",new JSONObject().put("id",Ledger.id()).put("name",Forms.value(name)).put("type","expense").put("amount",Forms.amount(amount,false)).put("account",account.id()).put("category",category.id()).put("next",next.toString()).put("frequency",new String[]{"monthly","weekly","yearly"}[freq.getSelectedItemPosition()]).put("active",true).put("automatic",false).put("matchNotifications",auto.isChecked()).put("anchorDay",next.getDayOfMonth()).put("shares",shares.value()).put("service",Icons.brand(Forms.value(name))));});}
}

